"""Build the read-only continuation reports from aggregate receipts and PR metadata."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
receipt = json.loads((ROOT / 'receipt.json').read_text())
triage = json.loads((ROOT / 'pr-triage.json').read_text())
public = json.loads((ROOT / 'public-check.json').read_text())
esc = lambda value: html.escape(str(value), quote=True)

def page(name, title, content):
    doc = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | GatorBait</title><link rel="stylesheet" href="report.css"></head><body><main><header><strong>GATOR<span>BAIT</span> MEDIA</strong><small>Codex continuation<br>Oct. 19, 2026 • UTC</small></header><nav aria-label="Report pages"><a href="index.html">Work desk</a><a href="revenue.html">Audience and memberships</a><a href="prs.html">PR triage</a><a href="plan.html">The Hive plan</a><a href="../muse-cover-review-20261019/index.html">Muse's cover review</a><a href="../muse-cover-review-20261019/social-draft.html">Social draft</a></nav>{content}<footer>Read-only findings and review drafts. No subscriber email, social post, Spaces announcement, site publish, plan change or automation switch was performed. Counts are dated observations; unavailable metrics remain unknown.</footer></main></body></html>'''
    (ROOT / name).write_text(doc)

page('index.html', 'Continuation work desk', '''
<p class="eyebrow">Current batch • One controller</p><h1>The work is organized.<br>The next cover needs its source.</h1>
<p class="lead">Codex owns this block. Muse prepares creative work; helpers return bounded findings. The active priorities are the magazine cover, social quality and the newsroom handoff.</p>
<div class="grid"><section class="card"><span class="tag">Cover</span><h2>Replacement pending</h2><p>The current "Beating Texas" cover is still live under magazine revision 119. No separate replacement file was identified in the supplied handoff. <a href="https://github.com/Presidente49/gatorbait-media-redesign/issues/34#issuecomment-6258469493">The exact asset has been requested from Jarvis.</a></p><p><a href="../muse-cover-review-20261019/index.html">Open Muse's phone review</a></p></section>
<section class="card"><span class="tag">Social</span><h2>One story. One clear card.</h2><p>A draft packet for Buddy Martin's Texas column uses a large headline, clear result, writer credit and a native-media export. It is ready for review, with no publishing action attached.</p><p><a href="../muse-cover-review-20261019/social-draft.html">Review the social packet</a></p></section>
<section class="card"><span class="tag">Measurement</span><h2>Reach remains unknown</h2><p>Metricool has no social networks connected. vidIQ has no authorized YouTube channels. Windsor paused analytics reads because four connections exceed its Free plan's one-account limit.</p><p>The warning row returned by Windsor is not a measurement of zero traffic.</p></section></div>
<section class="rows"><article class="row"><h2>Newsroom</h2><p>Chris Spears' Baylor column remains UNPUBLISHED with no cover attached. No new writer submissions or photos were found in the connected personal inbox; the business inbox was not accessible. The 20-item public RSS feed is newest first, with zero date inversions. No archived writer text was rewritten.</p></article>
<article class="row"><h2>Facts</h2><p>The current scoreboard agrees with the official ESPN check: Florida 5-2, 3-2 SEC; Texas final 27-24; Oct. 24 open date; Georgia Oct. 31 at 3:30 p.m. ET, ABC, Atlanta. Texas' No. 7 game-time rank stays on the recap. The October 18 poll has Texas No. 19. This was a core-facts check, not a full audit of every story claim.</p></article>
<article class="row"><h2>Site Pages</h2><p>PR #380 is merged. A fresh Wix read confirms embed af792630 at revision 3. The other worker's release checked 390, 430, 1366 and 1920 pixels. The pricing footer trace remains a baseline issue; no speculative patch was applied.</p></article>
<article class="row"><h2>Stats and pricing</h2><p>The missing stats producer and checked seven-game feed were restored in merged PR #387. Twenty-five tests and four-width local renderer checks pass. The public feed now returns HTTP 200 with Florida 5-2, 3-2 SEC; the native /florida-football-stats page still needs its Editor step. The old /plans-pricing route now resolves to /pricing-plans with HTTP 200. Placeholder text remains in the subscribe response; rendered visibility was not established by this HTTP check.</p></article>
<article class="row"><h2>Held work</h2><p>Soft signup and the Editor batch remain parked. Homepage 0c13f955, the magazine loader pin, sent email, payments, member access and all paused routines remain untouched. CFP graphics need primary-source checks and wording corrections before publication.</p></article></section>
<section class="note"><h2>Recommended next actions</h2><p>1. Identify the new cover, then perform the guarded magazine swap and four-width live QC.</p><p>2. Connect the intended business inbox to complete writer intake. Account connection changes remain Brenden's decision.</p><p>3. Review the social draft and use native social analytics to establish reach before choosing a distribution change.</p><p>4. Verify the restored stats feed publicly and include the missing native stats page in the Editor batch.</p><p>5. Keep the Editor/publish batch together for Brenden's explicit go.</p></section>
<section class="sources"><strong>Evidence</strong><ul><li><a href="public-check.json">HTTP/RSS receipt</a> and <a href="receipt.json">aggregate provider receipt</a></li><li><a href="https://github.com/Presidente49/gatorbait-media-redesign/issues/34#issuecomment-6258407678">Site Pages release evidence</a></li><li><a href="https://site.api.espn.com/apis/site/v2/sports/football/college-football/teams/57/schedule?season=2026&amp;seasontype=2">ESPN Florida schedule</a></li><li><a href="../muse-cover-review-20261019/cfp-review.html">CFP graphics source review</a></li></ul></section>''')

e = receipt['email']; c = receipt['contacts']; o = receipt['planOrders']
plan_rows = ''.join(f'<tr><td>{esc(p["planName"] or "Unmapped")} <small class="muted">({esc(p["planReference"])})</small></td><td>{p["active"]}</td><td>{p["createdSinceOct12"]}</td></tr>' for p in o['byPlan'])
page('revenue.html', 'Audience and membership snapshot', f'''
<p class="eyebrow">Revenue channels • Current counts</p><h1>Audience and memberships</h1><p class="lead">The email audience and plan-order inventory are available. Current YouTube performance and social reach are unavailable through the connected tools.</p>
<div class="grid"><section class="card"><h2>Opted-in addresses</h2><div class="number">{e['subscriptionStatus']['SUBSCRIBED']:,}</div><p>SUBSCRIBED records matched to unique CRM primary email addresses.</p></section><section class="card"><h2>Delivery screen</h2><div class="number">{e['subscribedDeliverableBeforeHolds']:,}</div><p>SUBSCRIBED + VALID or NOT_SET deliverability. Hold labels and all release checks still apply; this is not a send-ready audience.</p></section><section class="card"><h2>Active plan orders</h2><div class="number">{o['byStatus']['ACTIVE']:,}</div><p>Orders with active access. Trials, complimentary access and payment history were not reconciled; this is not a paid subscriber count.</p></section></div>
<section class="note"><h2>Five orders created since Oct. 12</h2><p>Three annual and two All Access monthly orders were created after Oct. 12, 2026, 04:00 UTC. These are acquisition records; their creation dates do not prove cash receipts, trial conversion or renewal revenue.</p></section>
<div class="table-wrap"><table><thead><tr><th>Plan</th><th>Active access orders</th><th>Created since Oct. 12</th></tr></thead><tbody>{plan_rows}</tbody></table></div>
<section class="rows"><article class="row"><h2>List coverage</h2><p>All {c['count']:,} CRM contacts paged, yielding {c['uniquePrimaryEmails']:,} unique primary email addresses. Subscription queries in batches of 20 matched {e['matched']:,}; {e['missing']} were unmatched, with no duplicate responses. Secondary addresses and subscriptions outside the CRM primary-address pool are outside this count. The unmatched addresses remain unverified.</p></article><article class="row"><h2>Order coverage</h2><p>Sequential pages of up to 50 orders exhausted at a short final page: {o['count']:,} records, including 970 canceled, 590 active, 91 draft and two ended. Plan IDs were used to separate similarly named products. Buyer deduplication and verified positive payments are outside this snapshot.</p></article><article class="row"><h2>Channels on file</h2><p>Memberships, the email list, YouTube and The Buddy Martin Show, Baker's Sporting Goods merchandise, and AdSense. No new offer, paywall, price, provider or spending plan was activated.</p></article><article class="row"><h2>Recommendation</h2><p>Keep the magazine open while the approved free-signup proposal remains parked. Establish native social and YouTube reporting before choosing a growth spend or interpreting reach. Do not treat missing analytics as zero.</p></article></section>
<section class="sources"><strong>Observed {esc(receipt['observedAt'])}</strong><p>Sources: Wix List Contacts, Query Email Subscriptions and Pricing Plans List Orders. The calculations ran inside the provider tool and returned aggregates only. No customer records, addresses or payment amounts are included.</p><p><a href="receipt.json">Aggregate receipt and access limitations</a></p></section>''')

pr_rows = []
for p in triage['prs']:
    recommendation = {'retain':'Retain / hold','review':'Review','superseded':'Superseded candidate','merged':'Already merged'}[p['recommendation']]
    pr_rows.append(f'''<article class="pr" data-kind="{p['recommendation']}"><div><a href="{esc(p['url'])}">#{p['id']}</a><p class="tag">{recommendation}</p></div><div><h2>{esc(p['title'])}</h2><p>{esc(p['main_concern'])}</p></div><div><h3>Next action</h3><p>{esc(p['next_action'])}</p><p><strong>Evidence:</strong> {esc(p['review_depth'])}. {esc(p['check_status'])}</p></div></article>''')
page('prs.html', 'Open PR triage', '''<p class="eyebrow">29 records reviewed • No closes or bulk merges</p><h1>Keep the useful work.<br>Leave obsolete releases alone.</h1><p class="lead">Six PRs are candidates for superseded status, eight should remain held, 14 need further review, and Site Pages #380 was already merged. These are triage recommendations, not publication clearance.</p><div class="note"><p>Fourteen requested PRs and #380 received direct metadata reads. Older entries are labeled search-only. Raw mergeable:false responses do not establish confirmed conflicts. Most CI notes below are author-reported historical evidence; no PR was certified ready for an immediate main merge.</p></div><div class="filters" role="group" aria-label="Filter PR recommendations"><button data-filter="all" aria-pressed="true">All 29</button><button data-filter="review" aria-pressed="false">Review 14</button><button data-filter="retain" aria-pressed="false">Retain / hold 8</button><button data-filter="superseded" aria-pressed="false">Superseded candidates 6</button><button data-filter="merged" aria-pressed="false">Merged 1</button></div><p id="count" aria-live="polite">29 records shown</p><section aria-label="Pull request records">''' + ''.join(pr_rows) + '''</section><section class="sources"><a href="pr-triage.json">Review metadata and source limits</a>. The list reflects the review snapshot on Oct. 19; re-read each PR before acting.</section><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.pr').forEach(x=>{x.hidden=b.dataset.filter!=='all'&&x.dataset.kind!==b.dataset.filter;if(!x.hidden)n++});document.getElementById('count').textContent=n+' records shown'}));</script>''')
